SELECT 'batch_033_7493b190_wav_09' AS batch_id,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-c4bc660d53934a4abe63a6ea0c65f452','sm-upload-3f53a506-748','sm-upload-5299f3bf-7dc','sm-upload-5ca9ba5e-a37','sm-upload-c20923fb-d86','sm-upload-c73ba5d8-d49','sm-upload-d094806c-15f','sm-upload-d4547cef-c76','sm-upload-ff03659c-53d') AND album_id='al-21bc6e49fd136ed02abc87af7493b190') AS candidate_masters_in_target,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-c4bc660d53934a4abe63a6ea0c65f452','sm-upload-3f53a506-748','sm-upload-5299f3bf-7dc','sm-upload-5ca9ba5e-a37','sm-upload-c20923fb-d86','sm-upload-c73ba5d8-d49','sm-upload-d094806c-15f','sm-upload-d4547cef-c76','sm-upload-ff03659c-53d') AND album_id='pending-uploads') AS candidate_masters_still_pending,(SELECT COUNT(*) FROM albums WHERE id='al-21bc6e49fd136ed02abc87af7493b190' AND name='FM404') AS target_album_rows,(SELECT song_count FROM albums WHERE id='al-21bc6e49fd136ed02abc87af7493b190') AS stored_song_count,(SELECT COALESCE(SUM(si.size),0) FROM song_instances si JOIN song_masters sm ON sm.id=si.master_id WHERE sm.album_id='al-21bc6e49fd136ed02abc87af7493b190') AS calculated_size;
